grid = [".......", "..#....", "....#..", ".#.....", "...#.#.", "......."]


def paths(blocked):
    dp = [0] * len(grid[0])
    dp[0] = 1
    for row in grid:
        for column, cell in enumerate(row):
            if blocked and cell == "#":
                dp[column] = 0
            elif column:
                dp[column] += dp[column - 1]
    return dp[-1]


print(f"without obstacles: {paths(False)}")
print(f"with obstacles: {paths(True)}")
